mapper.update:
UPDATE ai_slo_policy
SET evaluation_lease_owner = #{owner}, evaluation_lease_until_ms = #{leaseUntilMs}
WHERE id = #{id} AND enabled = 1 AND next_evaluation_at_ms <= #{nowMs}
  AND (evaluation_lease_owner IS NULL OR evaluation_lease_until_ms < #{nowMs})

UPDATE ai_slo_policy
SET next_evaluation_at_ms = #{nextEvaluationAtMs}, evaluation_lease_owner = NULL,
    evaluation_lease_until_ms = 0, evaluation_failures = evaluation_failures + 1,
    last_evaluated_at = #{evaluatedAt}, last_evaluation_status = 'FAILED',
    last_evaluation_error = #{error}
WHERE id = #{id} AND evaluation_lease_owner = #{owner}
